def preview(s, n=200):
    s = s.replace("\n", " ⏎ ")
    return s[:n] + ("…" if len(s) > n else "")
def get_text(msg):
    if isinstance(msg, str): return msg
    if isinstance(msg, dict):
        c = msg.get("content")
        if isinstance(c, str): return c
        if isinstance(c, list):
            out = []
            for blk in c:
                if isinstance(blk, dict):
                    t = blk.get("type")
                    if t == "text":
                        out.append(blk.get("text",""))
                    elif t == "tool_use":
                        name = blk.get("name","tool")
                        inp = blk.get("input",{})
                        if name == "Bash":
                            out.append(f"[Bash: {inp.get('command','')[:120]}]")
                        elif name in ("Read","Edit","Write"):
                            out.append(f"[{name}: {inp.get('file_path','')}]")
                        else:
                            out.append(f"[{name}: {json.dumps(inp)[:120]}]")
                    elif t == "tool_result":
                        c2 = blk.get("content","")
                        if isinstance(c2, list):
                            c2 = " ".join(b.get("text","") for b in c2 if isinstance(b, dict))
                        out.append(f"[result: {str(c2)[:120]}]")
            return "\n".join(out)
    return json.dumps(msg)[:200]

last = lines[-40:]
for ln in last:
    try:
        d = json.loads(ln)
    except Exception:
        continue
    typ = d.get("type") or d.get("role") or "?"
    msg = d.get("message", d)
    role = msg.get("role") if isinstance(msg, dict) else None
    text = get_text(msg)
    ts = d.get("timestamp","")
    tag = f"{typ}/{role}" if role else typ
    print(f"-- {tag} {ts}")
    print(preview(text, 600))
    print()
