// GET /api/v1/me/recap — per-agent recap aggregates for the CLI.
//
// Returns, for every agent the user has used in the window (and optionally
// every agent any contributor used on a scoped repo):
//   - me side: checkpoints + labels + skills + mcpServers + toolMix
//     (tokens intentionally omitted — the CLI sums metadata.json locally)
//   - contributors side: the same shape aggregated across all contributors
//     to the specified repo (requires ?repo=org/name)
//
// This endpoint consolidates three CLI operations into one request:
//   1. GET /api/v1/me/checkpoints       → list my checkpoints
//   2. POST /checkpoints/analyses/batch → analyses for each cp
//   3. GET /:org/:repo/overview/*       → contributor aggregates
//
// Without this endpoint the CLI has to do all three itself and attribute
// analyses to agents via the commits endpoint — a lot of round trips and
// brittle client-side joining. Centralizing on the server matches the
// pattern established by /me/activity (PR #1590).

import type { Context } from "hono"
import { Hono } from "hono"
import { describeRoute, resolver } from "hono-openapi"
import { z } from "zod"

import type { Env, Variables } from "../env"
import { getDb } from "../lib/db"
import { recordSpanError } from "../lib/telemetry"
import { parseTimeframeParams } from "./cache"

// AgentAggregate is the per-side per-agent payload. Same shape on both
// me and contributors sides so the CLI renderer can treat them uniformly.
interface AgentAggregate {
  checkpoints: number
  tokens: number
  transcriptTokens: number
  filesChanged: number
  labels: Array<{ label: string; count: number }>
  skills: Array<{ skill: string; count: number }>
  mcpServers: Array<{ name: string; count: number }>
  toolMix: {
    shell: number
    fileOps: number
    search: number
    mcp: number
    agent: number
    other: number
  }
}

// recapRoutes is mounted inside meRoutes at /me/recap. Bearer-auth is
// applied at the meRoutes level (requireBearerAuth); duplicating it here
// would double-execute the middleware.
const recapRoutes = new Hono<{ Bindings: Env; Variables: Variables }>()

const errorSchema = z.object({ error: z.string() })

const labelCountSchema = z.object({ label: z.string(), count: z.number() })
const skillCountSchema = z.object({ skill: z.string(), count: z.number() })
const mcpCountSchema = z.object({ name: z.string(), count: z.number() })
const toolMixSchema = z.object({
  shell: z.number(),
  fileOps: z.number(),
  search: z.number(),
  mcp: z.number(),
  agent: z.number(),
  other: z.number(),
})

const agentAggregateSchema = z.object({
  checkpoints: z.number(),
  tokens: z.number(),
  transcriptTokens: z.number(),
  filesChanged: z.number(),
  labels: z.array(labelCountSchema),
  skills: z.array(skillCountSchema),
  mcpServers: z.array(mcpCountSchema),
  toolMix: toolMixSchema,
})

