// merges their labels, skills, mcpServers, toolMix, transcriptTokens, and
// filesChanged onto the existing per-agent aggregate. Groups analysis
// lookups by repo_id so one query per repo (N+1 by repo, not by checkpoint).
async function mergeAnalysesInto(
  db: ReturnType<typeof getDb>,
  byAgent: Record<string, AgentAggregate>,
  cps: Array<{
    checkpoint_id: string
    repo_id: string
    agent: string | null
  }>,
): Promise<void> {
  if (cps.length === 0) return
  const byRepo = new Map<string, string[]>()
  for (const cp of cps) {
    if (!cp.repo_id || !cp.checkpoint_id) continue
    const arr = byRepo.get(cp.repo_id) ?? []
    arr.push(cp.checkpoint_id)
    byRepo.set(cp.repo_id, arr)
  }
  const analysesById = new Map<string, import("../types").StoredCheckpointAnalysis>()
  for (const [rid, ids] of byRepo) {
    const rows = await db.analyses.getByCheckpointIds(rid, ids)
    for (const row of rows) {
      if (row.status !== "complete" || !row.analysis_json) continue
      try {
        analysesById.set(row.checkpoint_id, JSON.parse(row.analysis_json))
      } catch {
        // ignore malformed analysis JSON
      }
    }
  }
  // Accumulate label / skill / mcp counts per agent then flatten.
  const labelCounts: Record<string, Record<string, number>> = {}
  const skillCounts: Record<string, Record<string, number>> = {}
  const mcpCounts: Record<string, Record<string, number>> = {}
  for (const cp of cps) {
    const agent = cp.agent ?? "unknown"
    const agg = byAgent[agent]
    if (!agg) continue
    const analysis = analysesById.get(cp.checkpoint_id)
    if (!analysis) continue
    agg.transcriptTokens += analysis.total_transcript_tokens ?? 0
    agg.filesChanged += analysis.totalFilesChanged ?? 0
    for (const lbl of analysis.extraction?.labels ?? []) {
      const m = (labelCounts[agent] ??= {})
      m[lbl] = (m[lbl] ?? 0) + 1
    }
    for (const sk of analysis.skillsUsed ?? []) {
      const m = (skillCounts[agent] ??= {})
      m[sk] = (m[sk] ?? 0) + 1
    }
    for (const mcp of analysis.mcpServersUsed ?? []) {
      const m = (mcpCounts[agent] ??= {})
      m[mcp.name] = (m[mcp.name] ?? 0) + (mcp.count ?? 1)
    }
    if (analysis.toolProfile?.categories) {
      const cats = analysis.toolProfile.categories
      agg.toolMix.shell += cats.shell?.count ?? 0
      agg.toolMix.fileOps += cats.fileOps?.count ?? 0
      agg.toolMix.search += cats.search?.count ?? 0
      agg.toolMix.mcp += cats.mcp?.count ?? 0
      agg.toolMix.agent += cats.agent?.count ?? 0
      agg.toolMix.other += cats.other?.count ?? 0
    }
  }
  for (const [agent, m] of Object.entries(labelCounts)) {
    byAgent[agent]!.labels = Object.entries(m).map(([label, count]) => ({ label, count }))
  }
  for (const [agent, m] of Object.entries(skillCounts)) {
    byAgent[agent]!.skills = Object.entries(m).map(([skill, count]) => ({ skill, count }))
  }
  for (const [agent, m] of Object.entries(mcpCounts)) {
    byAgent[agent]!.mcpServers = Object.entries(m).map(([name, count]) => ({ name, count }))
  }
}

function emptyAggregate(): AgentAggregate {
  return {
    checkpoints: 0,
    tokens: 0,
    transcriptTokens: 0,
    filesChanged: 0,
    labels: [],
    skills: [],
    mcpServers: [],
    toolMix: { shell: 0, fileOps: 0, search: 0, mcp: 0, agent: 0, other: 0 },
  }
}

export { recapRoutes }

