export function parseTimeframeParams(c: Context<{ Bindings: Env; Variables: Variables }>) {
  const timeframe = c.req.query("timeframe") || "last-6-months"
  const limitParam = c.req.query("limit")
  const parsedLimit = limitParam ? parseInt(limitParam, 10) : 500
  const limit = Number.isNaN(parsedLimit) || parsedLimit <= 0 ? 500 : Math.min(parsedLimit, 1000)

  const now = new Date()
  let startDate: Date

  switch (timeframe) {
    case "last-month":
      startDate = new Date(now)
      startDate.setDate(startDate.getDate() - 30)
      break
    case "last-3-months":
      startDate = new Date(now)
      startDate.setMonth(startDate.getMonth() - 3)
      break
    case "last-6-months":
    default:
      startDate = new Date(now)
      startDate.setMonth(startDate.getMonth() - 6)
      break
  }

  return { timeframe, limit, startDate, endDate: now }
}

