import { Hono } from "hono"
import { beforeEach, describe, expect, it, vi } from "vitest"

import type { Env, Variables } from "../env"

vi.mock("../lib/middleware", () => ({
  requireBearerAuth: vi.fn((_c, next) => next()),
  requireAuth: vi.fn((_c, next) => next()),
  requireAdmin: vi.fn((_c, next) => next()),
  optionalAuth: vi.fn((_c, next) => next()),
  rateLimitUnauthenticated: vi.fn((_c, next) => next()),
}))

vi.mock("../lib/telemetry", () => ({
  recordSpanError: vi.fn(),
}))

const mockGetWithCache = vi.fn()
const mockGetByUser = vi.fn()
const mockGetTeamOnUserRepos = vi.fn()
const mockGetByCheckpointIds = vi.fn()

vi.mock("../lib/db", () => ({
  getDb: () => ({
    users: { getWithCache: (...args: unknown[]) => mockGetWithCache(...args) },
    checkpoints: {
      getByUser: (...args: unknown[]) => mockGetByUser(...args),
      getTeamOnUserRepos: (...args: unknown[]) => mockGetTeamOnUserRepos(...args),
    },
    analyses: {
      getByCheckpointIds: (...args: unknown[]) => mockGetByCheckpointIds(...args),
    },
  }),
}))

import { recapRoutes } from "./recap"

// recapRoutes is mounted under /me/recap inside the parent router; in
// production the bearer auth middleware sets userId on the context. For
// these unit tests we mount the routes inside a wrapper that injects a
// constant userId so the handler can run.
function makeApp() {
  const app = new Hono<{ Bindings: Env; Variables: Variables }>()
  app.use("/*", async (c, next) => {
    c.set("userId", "user-1")
    await next()
  })
  app.route("/", recapRoutes)
  return app
}

const mockEnv = { ENTIRE_CACHE: {} } as unknown as Env
const mockExecutionCtx = { waitUntil: vi.fn(), passThroughOnException: vi.fn() }

function makeCheckpoint(overrides: Partial<Record<string, unknown>> = {}) {
  return {
    checkpoint_id: "cp-1",
    commit_sha: "sha-1",
    commit_message: "feat: stuff",
    commit_date: "2026-04-20T12:00:00Z",
    commit_author_github_id: 99,
    additions: 1,
    deletions: 0,
    files_changed: 1,
    repo_id: "repo-1",
    repo_full_name: "org/app",
    branch: "main",
    is_private: false,
    agent: "Claude Code",
    steps: 1,
    session_count: 1,
    input_tokens: 100,
    output_tokens: 50,
    ...overrides,
  }
}

describe("GET /me/recap", () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockGetWithCache.mockResolvedValue({ id: "user-1", github_id: 12345 })
    mockGetByUser.mockResolvedValue([])
    mockGetTeamOnUserRepos.mockResolvedValue([])
    mockGetByCheckpointIds.mockResolvedValue([])
  })

  function get(path: string) {
    return makeApp().request(path, { headers: {} }, { ...mockEnv, ...mockExecutionCtx })
  }

  it("returns null contributors and skips the team query when ?repo= is omitted", async () => {
    const res = await get("/")

    expect(res.status).toBe(200)
    const body = (await res.json()) as Record<string, unknown>

    expect(body.contributors).toBeNull()
    expect(body.repo).toBeNull()
    expect(mockGetTeamOnUserRepos).not.toHaveBeenCalled()
  })

  it("scopes both queries to the requested repo at the SQL level", async () => {
    mockGetByUser.mockResolvedValue([makeCheckpoint()])
    mockGetTeamOnUserRepos.mockResolvedValue([])

    const res = await get("/?repo=org/app")
    expect(res.status).toBe(200)

    expect(mockGetByUser).toHaveBeenCalledWith(
      "user-1",
      12345,
      expect.any(String),
      expect.any(String),
      expect.any(Number),
      "org/app",
    )
    expect(mockGetTeamOnUserRepos).toHaveBeenCalledWith(
      "user-1",
      12345,
      expect.any(String),
      expect.any(String),
      expect.any(Number),
      "org/app",
    )
  })

  it("counts distinct contributors by author id, not by commit_sha", async () => {
    mockGetByUser.mockResolvedValue([makeCheckpoint({ commit_author_github_id: 12345 })])
    mockGetTeamOnUserRepos.mockResolvedValue([
      // Author A makes two team commits — should count as ONE contributor,
      // not two as the previous commit_sha-based count would have done.
      makeCheckpoint({
        checkpoint_id: "cp-2",
        commit_sha: "sha-team-a-1",
        commit_author_github_id: 200,
      }),
      makeCheckpoint({
        checkpoint_id: "cp-3",
        commit_sha: "sha-team-a-2",
        commit_author_github_id: 200,
      }),
      makeCheckpoint({
        checkpoint_id: "cp-4",
        commit_sha: "sha-team-b-1",
        commit_author_github_id: 300,
      }),
    ])

    const res = await get("/?repo=org/app")
    const body = (await res.json()) as { contributors: { distinctUsers: number } }

    // Two team authors (200, 300) plus the requesting user = 3.
    expect(body.contributors.distinctUsers).toBe(3)
  })

  it("honours since/until query params over the timeframe enum", async () => {
    const since = "2026-04-20T00:00:00.000Z"
    const until = "2026-04-21T00:00:00.000Z"

    const res = await get(`/?since=${since}&until=${until}`)
    expect(res.status).toBe(200)
    const body = (await res.json()) as { since: string; until: string }
    expect(body.since).toBe(since)
    expect(body.until).toBe(until)
  })

  it("attributes analyses to checkpoints scoped by repo_id, not just checkpoint_id", async () => {
    // Two repos, two checkpoints sharing the same checkpoint_id "shared".
    // Each repo's analysis is unique. With the previous bug (key by
    // checkpoint_id alone), one analysis would clobber the other.
    mockGetByUser.mockResolvedValue([
      makeCheckpoint({
        repo_id: "repo-A",
        checkpoint_id: "shared",
        agent: "Claude Code",
      }),
      makeCheckpoint({
        repo_id: "repo-B",
        checkpoint_id: "shared",
        agent: "Codex",
      }),
    ])
    // First call (repo-A) returns labels=[bug_fix]; second (repo-B) returns
    // labels=[refactor]. Both should land on the right agent's card.
    mockGetByCheckpointIds.mockImplementation(async (repoId: string, _ids: string[]) => {
      if (repoId === "repo-A") {
        return [
          {
            checkpoint_id: "shared",
            status: "complete",
            analysis_json: JSON.stringify({ extraction: { labels: ["bug_fix"] } }),
          },
        ]
      }
      if (repoId === "repo-B") {
        return [
          {
            checkpoint_id: "shared",
            status: "complete",
            analysis_json: JSON.stringify({ extraction: { labels: ["refactor"] } }),
          },
        ]
      }
      return []
    })

    const res = await get("/")
    expect(res.status).toBe(200)
    const body = (await res.json()) as {
      agents: Record<string, { me: { labels: Array<{ label: string }> } }>
    }

    const claude = body.agents["Claude Code"]
    const codex = body.agents.Codex
    expect(claude.me.labels.map((l) => l.label)).toEqual(["bug_fix"])
    expect(codex.me.labels.map((l) => l.label)).toEqual(["refactor"])
  })
})

